INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190804, 54, 1, 2.801, 2, 3, "2022/01/27 14:59:59", "2022/01/18 12:00:00", 10083003, "受け取ることができる\n報酬があるようです\n確認してみてください", 10083, "カリン", 0.0, -416.5);
