INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190804, 55, 1, 5.506, 2, 1, "2022/01/27 14:59:59", "2022/01/18 12:00:00", 10083006, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 10083, "カリン", 0.0, -363.0);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190804, 55, 2, 1.216, 1, 2, "2022/01/27 14:59:59", "2022/01/18 12:00:00", 10083007, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 10083, "カリン", 0.0, -363.0);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190804, 56, 2, 1.539, 1, 3, "2022/01/27 14:59:59", "2022/01/18 12:00:00", 10083008, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 10083, "カリン", 0.0, -363.0);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190804, 56, 2, 1.875, 1, 4, "2022/01/27 14:59:59", "2022/01/18 12:00:00", 10083009, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 10083, "カリン", 0.0, -363.0);
