INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 53, 1, 3.099, 2, 2, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025002, "ミッションをクリアして、\n報酬をゲットしましょう！", 20025, "カリン", 0.0, -416.5);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 54, 1, 2.801, 2, 3, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025003, "受け取ることができる\n報酬があるようです\n確認してみてください", 20025, "カリン", 0.0, -416.5);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 54, 2, 0.0, 2, 4, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025004, "報酬がもらえますよ！\nチェックしてみてください", 20025, "カリン", 0.0, -416.5);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 57, 1, 0.0, 1, 5, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025005, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 20025, "カリン", 0.0, -416.5);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 55, 1, 5.506, 2, 1, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025006, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 20025, "カリン", 0.0, -363.0);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 55, 2, 1.216, 1, 2, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025007, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 20025, "カリン", 0.0, -363.0);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 56, 2, 1.539, 1, 3, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025008, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 20025, "カリン", 0.0, -363.0);
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (190801, 56, 2, 1.875, 1, 4, "2030/01/01 14:59:59", "2022/03/17 15:00:00", 20025009, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 20025, "カリン", 0.0, -363.0);
